# Measures a GLB generated by Meshy (Higgsfield, multi_image_to_3d) to fill a character's cuts.json:
#  - prints every bone's pivot in metres;
#  - prints, per centimetre of height between 0.80 and 1.65 m, how many vertices the middle column of the body has
#    (|x| < 5 cm) and how deep it is: a seam shows as a peak of vertices or a dip in depth;
#  - with --render, renders orthographic front, side and back views at a known scale, to read heights and widths off
#    the image: 1000 x 1000 pixels, centred on --centre (height in metres) and --span metres tall.
# Usage: blender -b --factory-startup --python-exit-code 1 -P measure_meshy_model.py -- model.glb
#        [--render out_prefix [--centre 0.9] [--span 2.0]]
import bpy, sys
from collections import defaultdict
from mathutils import Vector
args = sys.argv[sys.argv.index('--') + 1:]
src = args[0]
opt = lambda name, default: args[args.index(name) + 1] if name in args else default
bpy.ops.wm.read_factory_settings(use_empty=True)
bpy.ops.import_scene.gltf(filepath=src)
arm = next(o for o in bpy.data.objects if o.type == 'ARMATURE')
body = max((o for o in bpy.data.objects if o.type == 'MESH'), key=lambda o: len(o.data.vertices))
MW, BW = arm.matrix_world, body.matrix_world
print("BONES (pivot, metres)")
for b in arm.data.bones:
    h = MW @ b.head_local
    print(f"  {b.name:16s} ({h.x:+.3f}, {h.y:+.3f}, {h.z:.3f})")
vs = [BW @ v.co for v in body.data.vertices]
print("SIZE", "min", [round(min(v[i] for v in vs), 3) for i in range(3)], "max", [round(max(v[i] for v in vs), 3) for i in range(3)],
      "vertices", len(vs), "triangles", sum(len(p.vertices) - 2 for p in body.data.polygons))
count = defaultdict(int); front = {}; back = {}
for v in vs:
    if abs(v.x) < 0.05:
        k = round(v.z * 100); count[k] += 1
        front[k] = min(front.get(k, 9), v.y); back[k] = max(back.get(k, -9), v.y)
print("MIDDLE COLUMN  height  vertices  depth (front to back, the character faces -y)")
for k in sorted(count):
    if 80 <= k <= 165:
        print(f"  {k / 100:.2f}  {count[k]:3d} {'#' * min(count[k], 60):60s}  {front[k]:+.3f} .. {back[k]:+.3f}")
if '--render' in args:
    out = opt('--render', 'view'); centre = float(opt('--centre', 0.9)); span = float(opt('--span', 2.0))
    for o in bpy.data.objects:
        if o.type == 'ARMATURE' and o.animation_data: o.animation_data_clear()
    sc = bpy.context.scene
    sc.render.engine = 'BLENDER_WORKBENCH'
    sc.display.shading.light = 'STUDIO'; sc.display.shading.color_type = 'SINGLE'
    sc.display.shading.single_color = (0.75, 0.75, 0.75); sc.display.shading.show_cavity = True
    sc.render.resolution_x = sc.render.resolution_y = 1000
    cd = bpy.data.cameras.new('measure'); cd.type = 'ORTHO'; cd.ortho_scale = span
    cam = bpy.data.objects.new('measure', cd); sc.collection.objects.link(cam); sc.camera = cam
    target = Vector((0, 0, centre))
    for name, offset in (('front', (0, -5, 0)), ('side', (5, 0, 0)), ('back', (0, 5, 0))):
        cam.location = target + Vector(offset)
        cam.rotation_euler = (target - cam.location).to_track_quat('-Z', 'Y').to_euler()
        sc.render.filepath = f"{out}_{name}.png"; bpy.ops.render.render(write_still=True)
    print(f"RENDER {out}_front/side/back.png: {1000 / span:.0f} px per metre; row 500 is z = {centre}, column 500 is x = 0 "
          f"(front: +x to the right; side: front of the body to the left)")
